const { Given, When, Then } = require('@cucumber/cucumber');
const chai = require('chai');
const path = require('node:path');
const fs = require('node:fs');
const Ajv = require('ajv');

const { expect } = chai;

// -- HELPERS ----------------------------------------------------------------

function getTodoItems(document) {
  return Array.from(document.querySelectorAll('.todo-list li'));
}

function findTodoItem(document, text) {
  return getTodoItems(document).find(
    (li) => li.querySelector('label').textContent.trim() === text
  );
}

function waitForTick() {
  return new Promise((r) => setTimeout(r, 0));
}

// Directly update localStorage without app reload. Reads from this.localStorage
// and writes back; then re-renders the app by creating-and-removing a temporary
// element trick, or simply set localStorage and let the app re-read it on next render.
// We cannot call render() directly, so we use the app's own toggle-all handler
// as a side effect, or we set localStorage and then trigger a full re-init via
// app's route change or similar.

// Safer helper: write todos to the CURRENT window's localStorage (the same one
// the app uses), then trigger a render by dispatching a custom event the app
// doesn't react to, but then force a re-read. We do this by patching the app's
// render loop: we write localStorage and then click nothing; the app will read
// from localStorage on its next render cycle.
// Since we cannot easily trigger a render without the app's API, we'll just
// set localStorage and then re-init via the app's own disposal trick using
// the fact that the app reads localStorage on every render() — so we need to
// call render(). The simplest approach: create a hidden input, type into it to
// trigger the new-todo handler (which renders), but that would add a todo.
// Instead, we write localStorage then reload via hashchange without navigation.
function forceRenderFromStore(self) {
  // read and write back the same data — the app renders already on some events.
  // We'll use a hashchange event to trigger a re-render cycle.
  var currentHash = self.window.location.hash;
  self.window.location.hash = '#/nonexistent';
  self.window.dispatchEvent(new self.window.Event('hashchange'));
  self.window.location.hash = currentHash || '#/';
  self.window.dispatchEvent(new self.window.Event('hashchange'));
}

// -- GIVEN ------------------------------------------------------------------

Given('the user opens the TodoMVC app', async function () {
  await waitForTick();
});

Given('the app has loaded with no todos', async function () {
  this.localStorage.clear();
  await this.disposeApp();
  this.loadApp();
  await waitForTick();
});

Given('the todo list is empty', async function () {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(0);
});

Given('the todo list contains an item {string}', async function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await waitForTick();
});

Given('the todo list contains items {string} and {string}', async function (text1, text2) {
  const input = this.document.querySelector('.new-todo');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await waitForTick();
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await waitForTick();
});

Given('the item {string} is already completed', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const checkbox = li.querySelector('.toggle');
  if (!checkbox.checked) {
    checkbox.checked = true;
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    await waitForTick();
  }
});

Given('the item {string} is completed', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const checkbox = li.querySelector('.toggle');
  if (!checkbox.checked) {
    checkbox.checked = true;
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    await waitForTick();
  }
});

Given('no items are completed', async function () {
  // Use the toggle-all to uncheck all items
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll.checked) {
    toggleAll.checked = false;
    toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    await waitForTick();
  }
  // Also ensure individual items are not checked
  const items = getTodoItems(this.document);
  items.forEach((li) => {
    const checkbox = li.querySelector('.toggle');
    if (checkbox.checked) {
      checkbox.checked = false;
      checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  });
  await waitForTick();
});

Given('both items are completed', async function () {
  // Use toggle-all to check all items
  const toggleAll = this.document.querySelector('.toggle-all');
  if (!toggleAll.checked) {
    toggleAll.checked = true;
    toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    await waitForTick();
  }
});

Given('the app has loaded with todos from localStorage', async function () {
  await waitForTick();
});

// -- WHEN -------------------------------------------------------------------

When('the user types {string} into the new-todo input and presses Enter', async function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await waitForTick();
});

When('the user clicks the toggle checkbox for {string}', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const checkbox = li.querySelector('.toggle');
  checkbox.checked = !checkbox.checked;
  checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  await waitForTick();
});

When('the user clicks the mark-all-as-complete toggle', async function () {
  const toggle = this.document.querySelector('.toggle-all');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  await waitForTick();
});

When('the user marks {string} as completed', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const checkbox = li.querySelector('.toggle');
  if (!checkbox.checked) {
    checkbox.checked = true;
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
  await waitForTick();
});

When('the user clicks the {string} button', async function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('button.clear-completed');
    btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
    await waitForTick();
  }
});

When('the user destroys the todo {string}', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const btn = li.querySelector('button.destroy');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
  await waitForTick();
});

When('the user double-clicks the label for {string}', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  await waitForTick();
});

When('the user edits {string} to {string} and presses Enter', async function (oldText, newText) {
  const li = findTodoItem(this.document, oldText);
  expect(li).to.not.be.undefined;
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  await waitForTick();
  const editInput = li.querySelector('input.edit');
  editInput.value = newText;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  await waitForTick();
});

When('the user edits {string} to {string} and blurs the edit input', async function (oldText, newText) {
  const li = findTodoItem(this.document, oldText);
  expect(li).to.not.be.undefined;
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  await waitForTick();
  const editInput = li.querySelector('input.edit');
  editInput.value = newText;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  await waitForTick();
});

When('the user edits {string} to {string} and presses Escape', async function (oldText, newText) {
  const li = findTodoItem(this.document, oldText);
  expect(li).to.not.be.undefined;
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  await waitForTick();
  const editInput = li.querySelector('input.edit');
  editInput.value = newText;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
  await waitForTick();
});

When('the user reloads the app', async function () {
  // Preserve localStorage across happy-dom window recreation
  var preservedData = {};
  var len = this.localStorage.length;
  for (var i = 0; i < len; i++) {
    var key = this.localStorage.key(i);
    preservedData[key] = this.localStorage.getItem(key);
  }
  await this.disposeApp();
  // Create a new Window and restore data before app initializes
  const { Window } = require('happy-dom');
  const fs = require('node:fs');
  const path = require('node:path');
  const ROOT = path.resolve(__dirname, '..', '..');
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');
  const appSource = fs.readFileSync(appPath, 'utf8');
  this.window = new (require('happy-dom').Window)({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;
  this.document.write(fs.readFileSync(indexPath, 'utf8'));
  this.document.close();
  // Restore preserved data before app initializes
  for (var key in preservedData) {
    if (preservedData.hasOwnProperty(key)) {
      this.localStorage.setItem(key, preservedData[key]);
    }
  }
  this.window.eval(appSource);
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));
  const w = this.window;
  this.document.addEventListener('click', (e) => {
    const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
    if (!a) return;
    const next = a.getAttribute('href');
    if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
  }, true);
  await waitForTick();
});

When('the user inspects the localStorage data for {string}', async function (key) {
  this.inspectedKey = key;
  const raw = this.localStorage.getItem(key);
  this.inspectedData = raw ? JSON.parse(raw) : [];
});

When('the user navigates to the default route', async function () {
  this.navigate('#/');
  await waitForTick();
});

When('the user navigates to the Active filter', async function () {
  this.navigate('#/active');
  await waitForTick();
});

When('the user navigates to the Completed filter', async function () {
  this.navigate('#/completed');
  await waitForTick();
});

When('the user marks {string} as active', async function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  const checkbox = li.querySelector('.toggle');
  if (checkbox.checked) {
    checkbox.checked = false;
    checkbox.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
  await waitForTick();
});

// -- THEN -------------------------------------------------------------------

Then('the main section should not be visible', function () {
  const main = this.document.querySelector('section.main');
  const style = this.window.getComputedStyle(main);
  expect(style.display).to.equal('none');
});

Then('the footer section should not be visible', function () {
  const footer = this.document.querySelector('footer.footer');
  const style = this.window.getComputedStyle(footer);
  expect(style.display).to.equal('none');
});

Then('the todo list should contain {int} item', function (count) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(count);
});

Then('the new item should display the text {string}', function (text) {
  const items = getTodoItems(this.document);
  expect(items.length).to.be.at.least(1);
  const lastItem = items[items.length - 1];
  expect(lastItem.querySelector('label').textContent.trim()).to.equal(text);
});

Then('the new-todo input should be cleared', function () {
  const input = this.document.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

Then('the todo list should contain an item with the text {string}', function (text) {
  const item = findTodoItem(this.document, text);
  expect(item).to.not.be.undefined;
});

Then('the todo list should still be empty', function () {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(0);
});

Then('the item {string} should be marked as completed', function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  expect(li.classList.contains('completed')).to.be.true;
});

Then('the mark-all-as-complete checkbox should be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  expect(toggle.checked).to.be.true;
});

Then('every todo in the list should be marked as completed', function () {
  const items = getTodoItems(this.document);
  items.forEach((li) => {
    expect(li.classList.contains('completed')).to.be.true;
  });
});

Then('no todo in the list should be marked as completed', function () {
  const items = getTodoItems(this.document);
  items.forEach((li) => {
    expect(li.classList.contains('completed')).to.be.false;
  });
});

Then('the mark-all-as-complete checkbox should not be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  expect(toggle.checked).to.be.false;
});

Then('the todo-count should show {string}', function (expected) {
  const countEl = this.document.querySelector('.todo-count');
  expect(countEl.textContent.trim()).to.equal(expected);
});

Then('the todo-count should contain a strong element with the active count', function () {
  const countEl = this.document.querySelector('.todo-count');
  const strong = countEl.querySelector('strong');
  expect(strong).to.not.be.undefined;
  expect(strong.textContent.trim()).to.match(/^\d+$/);
});

Then('the todo list should contain only {string}', function (text) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(1);
  expect(items[0].querySelector('label').textContent.trim()).to.equal(text);
});

Then('the item {string} should not appear in the list', function (text) {
  const item = findTodoItem(this.document, text);
  expect(item).to.be.undefined;
});

Then('the clear-completed button should not be visible', function () {
  const btn = this.document.querySelector('button.clear-completed');
  const style = this.window.getComputedStyle(btn);
  expect(style.display).to.equal('none');
});

Then('the item\'s li should have the class {string}', function (cls) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  expect(editingLi).to.not.be.undefined;
  expect(editingLi.classList.contains(cls)).to.be.true;
});

Then('the edit input should be focused', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  expect(editingLi).to.not.be.undefined;
  const editInput = editingLi.querySelector('input.edit');
  expect(this.document.activeElement).to.equal(editInput);
});

Then('the edit input should contain the text {string}', function (text) {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  expect(editingLi).to.not.be.undefined;
  const editInput = editingLi.querySelector('input.edit');
  expect(editInput.value).to.equal(text);
});

Then('the item should display the text {string}', function (text) {
  const items = getTodoItems(this.document);
  const found = items.find((li) => li.querySelector('label').textContent.trim() === text);
  expect(found).to.not.be.undefined;
});

Then('the item\'s li should not have the class {string}', function (cls) {
  const items = getTodoItems(this.document);
  items.forEach((li) => {
    expect(li.classList.contains(cls)).to.be.false;
  });
});

Then('the item should display the original text {string}', function (text) {
  const item = findTodoItem(this.document, text);
  expect(item).to.not.be.undefined;
  expect(item.querySelector('label').textContent.trim()).to.equal(text);
});

Then('the todo list should contain {int} items', function (count) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(count);
});

Then('the item {string} should be active', function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  expect(li.classList.contains('completed')).to.be.false;
});

Then('the item {string} should be completed', function (text) {
  const li = findTodoItem(this.document, text);
  expect(li).to.not.be.undefined;
  expect(li.classList.contains('completed')).to.be.true;
});

Then('every item in the stored list conforms to the {string} schema in {string}', async function (schemaName, schemaPath) {
  const schemaFullPath = path.resolve(__dirname, '..', '..', schemaPath);
  const schemaText = fs.readFileSync(schemaFullPath, 'utf8');
  const schema = JSON.parse(schemaText);
  const ajv = new Ajv();
  const validate = ajv.compile(schema);
  const data = this.inspectedData || [];
  data.forEach((item, i) => {
    const valid = validate(item);
    expect(valid, `Item ${i} does not conform: ${JSON.stringify(validate.errors)}`).to.be.true;
  });
});

Then('the todo list should show {int} items', function (count) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(count);
});

Then('the {string} filter link should have the class {string}', function (filterName, cls) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  const link = this.document.querySelector(`.filters a[href="${href}"]`);
  expect(link).to.not.be.undefined;
  expect(link.classList.contains(cls)).to.be.true;
});

Then('the todo list should show {int} item', function (count) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(count);
});

Then('that item should be {string}', function (text) {
  const items = getTodoItems(this.document);
  expect(items.length).to.equal(1);
  expect(items[0].querySelector('label').textContent.trim()).to.equal(text);
});

Then('the {string} filter link should not have the class {string}', function (filterName, cls) {
  const filterMap = { 'All': '#/', 'Active': '#/active', 'Completed': '#/completed' };
  const href = filterMap[filterName];
  const link = this.document.querySelector(`.filters a[href="${href}"]`);
  if (link) {
    expect(link.classList.contains(cls)).to.be.false;
  }
});

Then('the todo list should show only uncompleted items', function () {
  const items = getTodoItems(this.document);
  items.forEach((li) => {
    expect(li.classList.contains('completed')).to.be.false;
  });
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

(function () {
  'use strict';

  var STORAGE_KEY = 'todos-javascript';
  var ENTER_KEY = 13;

  // ----- Model -----

  function TodoStore(key) {
    this.key = key;
  }

  TodoStore.prototype.load = function () {
    var raw = localStorage.getItem(this.key);
    return raw ? JSON.parse(raw) : [];
  };

  TodoStore.prototype.save = function (todos) {
    localStorage.setItem(this.key, JSON.stringify(todos));
  };

  // ----- View -----

  function TodoApp(element, store) {
    this.element = element;
    this.store = store;
    this.newTodo = element.querySelector('.new-todo');
    this.main = element.querySelector('.main');
    this.footer = element.querySelector('.footer');
    this.todoList = element.querySelector('.todo-list');
    this.todoCount = element.querySelector('.todo-count');
    this.clearCompleted = element.querySelector('.clear-completed');
    this.toggleAll = element.querySelector('.toggle-all');
    this.filters = element.querySelector('.filters');

    // Restore persisted filter on init
    var savedFilter = localStorage.getItem('todos-javascript-filter');
    if (savedFilter === 'active') {
      window.location.hash = '#/active';
    } else if (savedFilter === 'completed') {
      window.location.hash = '#/completed';
    } else {
      window.location.hash = '#/';
    }

    this.bindEvents();
    this.render();
  }

  TodoApp.prototype.getFilter = function () {
    var hash = window.location.hash;
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  };

  TodoApp.prototype.bindEvents = function () {
    var self = this;

    this.newTodo.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        var title = self.newTodo.value.trim();
        if (title) {
          var todos = self.store.load();
          todos.push({
            id: Date.now().toString(),
            title: title,
            completed: false
          });
          self.store.save(todos);
          self.newTodo.value = '';
          self.render();
        }
      }
    });

    window.addEventListener('hashchange', function () {
      self.render();
    });

    // Delegate toggle checkbox changes
    this.todoList.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var title = label.textContent;
        var todos = self.store.load();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].title === title) {
            todos[i].completed = e.target.checked;
            break;
          }
        }
        self.store.save(todos);
        self.render();
      }
    });

    // Toggle-all checkbox
    this.toggleAll.addEventListener('change', function () {
      var checked = self.toggleAll.checked;
      var todos = self.store.load();
      for (var i = 0; i < todos.length; i++) {
        todos[i].completed = checked;
      }
      self.store.save(todos);
      self.render();
    });

    // Clear completed button
    this.clearCompleted.addEventListener('click', function () {
      var todos = self.store.load();
      todos = todos.filter(function (t) { return !t.completed; });
      self.store.save(todos);
      self.render();
    });

    // Delegate destroy button clicks
    this.todoList.addEventListener('click', function (e) {
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var title = label.textContent;
        var todos = self.store.load();
        for (var i = 0; i < todos.length; i++) {
          if (todos[i].title === title) {
            todos.splice(i, 1);
            break;
          }
        }
        self.store.save(todos);
        self.render();
      }
    });

    // Delegate label double-click for editing
    this.todoList.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (label) {
        var li = label.closest('li');
        li.classList.add('editing');
        var editInput = li.querySelector('input.edit');
        editInput.value = li.querySelector('label').textContent;
        editInput.focus();
      }
    });

    // Delegate edit keydown and blur
    this.todoList.addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var originalTitle = label.textContent;
        var newTitle = e.target.value.trim();

        if (e.keyCode === 13) {
          // Enter - save
          if (newTitle) {
            var todos = self.store.load();
            for (var i = 0; i < todos.length; i++) {
              if (todos[i].title === originalTitle) {
                todos[i].title = newTitle;
                break;
              }
            }
            self.store.save(todos);
          } else {
            // Empty - destroy
            var todos = self.store.load();
            for (var i = 0; i < todos.length; i++) {
              if (todos[i].title === originalTitle) {
                todos.splice(i, 1);
                break;
              }
            }
            self.store.save(todos);
          }
          self.render();
        } else if (e.keyCode === 27) {
          // Escape - discard
          self.render();
        }
      }
    });

    this.todoList.addEventListener('blur', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        var label = li.querySelector('label');
        var originalTitle = label.textContent;
        var newTitle = e.target.value.trim();

        if (newTitle && newTitle !== originalTitle) {
          var todos = self.store.load();
          for (var i = 0; i < todos.length; i++) {
            if (todos[i].title === originalTitle) {
              todos[i].title = newTitle;
              break;
            }
          }
          self.store.save(todos);
          self.render();
        }
      }
    }, true);
  };

  /**
   * @planks-provisional("features/todos.feature:Mark-all toggle preserves previous DOM node references")
   * @planks-provisional("features/todos.feature:Adding a new todo preserves existing DOM node references")
   *
   * PERTURBATION: render() replaces this.todoList.innerHTML on every call,
   * destroying all existing <li> DOM nodes and recreating them. Any external
   * reference to a specific li element becomes detached from the DOM after
   * render(). The acceptance suite (Cypress) fails because cached aliases
   * (@todos, @firstTodo) point to stale nodes. Fix by preserving existing DOM
   * nodes and only updating their state, rather than full innerHTML replacement.
   * remove when fixed.
   *
   * throw new Error("PERTURBATION: consider current durable context; remove when fixed");
   */
  TodoApp.prototype.render = function () {
    var todos = this.store.load();
    var filter = this.getFilter();

    // Apply filter
    var visibleTodos;
    if (filter === 'active') {
      visibleTodos = todos.filter(function (t) { return !t.completed; });
    } else if (filter === 'completed') {
      visibleTodos = todos.filter(function (t) { return t.completed; });
    } else {
      visibleTodos = todos;
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // Render visible todo items
    var html = '';
    for (var i = 0; i < visibleTodos.length; i++) {
      var t = visibleTodos[i];
      var cls = t.completed ? 'completed' : '';
      html += '<li class="' + cls + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (t.completed ? ' checked' : '') + '>' +
        '<label>' + this.escapeHtml(t.title) + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + this.escapeHtml(t.title) + '">' +
        '</li>';
    }
    this.todoList.innerHTML = html;

    // Show/hide main and footer based on whether there are any todos
    if (todos.length === 0) {
      this.main.style.display = 'none';
      this.footer.style.display = 'none';
    } else {
      this.main.style.display = 'block';
      this.footer.style.display = 'block';
    }

    // Update toggle-all checkbox
    this.toggleAll.checked = todos.length > 0 && activeCount === 0;

    // Update todo-count
    var word = activeCount === 1 ? 'item' : 'items';
    this.todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Show/hide clear-completed button
    if (completedCount > 0) {
      this.clearCompleted.style.display = 'block';
    } else {
      this.clearCompleted.style.display = 'none';
    }

    // Update filter link selected state
    var filterLinks = this.filters.querySelectorAll('a');
    for (var i = 0; i < filterLinks.length; i++) {
      var a = filterLinks[i];
      var href = a.getAttribute('href');
      if ((filter === 'all' && href === '#/') ||
          (filter === 'active' && href === '#/active') ||
          (filter === 'completed' && href === '#/completed')) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }

    // Persist filter
    localStorage.setItem('todos-javascript-filter', filter);
  };

  TodoApp.prototype.escapeHtml = function (text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  };

  // ----- Bootstrap -----

  var app = new TodoApp(document.querySelector('.todoapp'), new TodoStore(STORAGE_KEY));
})();

